#[test]
fn 保存先がディレクトリのとき保存はIOの失敗を返す() {
    let dir = TempDir::new("edge");
    let known = KnownContentRegistry::new();
    let path = chosen_file_path(&dir, "document.dcmp");
    fs::create_dir(&path).expect("ディレクトリを作成できる");

    let error = io::save(&known, &path, r#"{"a":1}"#).expect_err("保存に失敗する");

    assert!(matches!(error, DocumentIoError::Io { .. }));
}

#[test]
fn 保存の失敗には保存先のパスが載る() {
    let dir = TempDir::new("edge");
    let known = KnownContentRegistry::new();
    let path = chosen_file_path(&dir, "document.dcmp");
    fs::create_dir(&path).expect("ディレクトリを作成できる");

    let error = io::save(&known, &path, r#"{"a":1}"#).expect_err("保存に失敗する");

    // 一時ファイル名 `.document.dcmp.<pid>.<n>.tmp` もファイル名を含むので、フルパスで照合する
    let destination = path.display().to_string();
    assert!(
        error.message().contains(&destination),
        "エラーメッセージに保存先のパスが含まれていない: {}",
        error.message()
    );
}

#[test]
fn 存在しないディレクトリ配下への保存は失敗する() {
    let dir = TempDir::new("edge");
    let known = KnownContentRegistry::new();

    let error = io::save(
        &known,
        &chosen_file_path(&dir, "missing/document.dcmp"),
        r#"{"a":1}"#,
    )
    .expect_err("保存に失敗する");

    assert!(matches!(error, DocumentIoError::NotFound { .. }));
}

#[test]
fn 保存に失敗したとき一時ファイルが残らない() {
    let dir = TempDir::new("edge");
    let known = KnownContentRegistry::new();

    // 書き込み先をディレクトリにすることで、一時ファイルの作成後に rename を失敗させる
    let path = chosen_file_path(&dir, "document.dcmp");
    fs::create_dir(&path).expect("ディレクトリを作成できる");

    io::save(&known, &path, r#"{"a":1}"#).expect_err("保存に失敗する");

    assert_eq!(dir.file_names(), vec!["document.dcmp".to_string()]);
}

#[test]
fn 書き込みを繰り返している最中に読み続けても常に完全なJSONが読める() {
    let dir = TempDir::new("atomicity");
    let path = chosen_file_path(&dir, "document.dcmp");
    let known = KnownContentRegistry::new();

    // アトミックでない書き込みなら途中状態が観測できる程度の大きさにする
    let before = document("before", 4000);
    let after = document("after", 4000);

    io::save(&known, &path, &before).expect("初回の保存に成功する");

    let stop = Arc::new(AtomicBool::new(false));
    let reader_stop = Arc::clone(&stop);
    let reader_path = path.clone();
    let readable = [before.clone(), after.clone()];

    let reader = thread::spawn(move || {
        let mut read_count = 0usize;
        while !reader_stop.load(Ordering::Relaxed) {
            let content = io::load(&reader_path).expect("読み込みに成功する");

            assert!(
                serde_json::from_str::<serde_json::Value>(&content).is_ok(),
                "不完全な JSON が読めた ({} バイト)",
                content.len()
            );
            assert!(
                readable.contains(&content),
                "書き込み前でも書き込み後でもない内容が読めた ({} バイト)",
                content.len()
            );

            read_count += 1;
        }
        read_count
    });

    for round in 0..50 {
        let content = if round % 2 == 0 { &after } else { &before };
        io::save(&known, &path, content).expect("保存に成功する");
    }

    stop.store(true, Ordering::Relaxed);
    let read_count = reader
        .join()
        .expect("読み込み側が不完全な内容を観測していない");

    assert!(read_count > 0, "読み込みが 1 度も行われていない");
}

